import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static int[] par;
    static int comp_count;

    static int find_par(int x) {
        if (par[x] == x) return x;
        return par[x] = find_par(par[x]);
    }

    static void unite(int a, int b) {
        a = find_par(a);
        b = find_par(b);
        if (a == b) return;
        comp_count--;
        par[b] = a;
    }

    static long mod_pow(long base, int e) {
        if (e == 0) return 1;
        long half_pow = mod_pow(base, e / 2);
        long res = (half_pow * half_pow) % MOD;
        if ((e & 1) == 1) res = (res * base) % MOD;
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(mod_pow(p, (int)(p - 1)));
            sc.close();
            return;
        }

        par = new int[(int)p];
        comp_count = (int)(p - (k > 1 ? 1 : 0));
        for (int i = 1; i < p; i++) {
            par[i] = i;
        }

        for (int i = 1; i < p; i++) {
            unite(i, (int)((i * k) % p));
        }

        System.out.println(mod_pow(p, comp_count));
        sc.close();
    }
}
